mkitem!{mkimpl!{# [doc = " Collapses all unit items from an iterator into one."] # [doc = ""] # [doc = " This is more useful when combined with higher-level abstractions, like"] # [doc = " collecting to a `Result<(), E>` where you only care about errors:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::io::*;"] # [doc = " let data = vec![1, 2, 3, 4, 5];"] # [doc = " let res: Result<()> = data.iter()"] # [doc = "     .map(|x| writeln!(stdout(), \"{x}\"))"] # [doc = "     .collect();"] # [doc = " assert!(res.is_ok());"] # [doc = " ```"] # [stable (feature = "unit_from_iter" , since = "1.23.0")] impl FromIterator < () > for () { fn from_iter < I : IntoIterator < Item = () > > (iter : I) -> Self { iter . into_iter () . for_each (| () | { }) } }}}
